# extract_invoice_fields.py\n# [SAME-SCENARIO] extracts vendor, date, total, and line-item fields from an invoice\n\nfrom document_client import DocumentClient\nfrom document_models import InvoiceExtractionRequest, InvoiceExtractionResponse\n\n# Using Mindee Invoice OCR as the concrete provider\n# Required environment variable: MINDEE_API_KEY\n\ndef extract_invoice_fields(file_path: str) -> InvoiceExtractionResponse:\n    # Initialize client with Mindee SDK\n    client = DocumentClient(service="Mindee", api_key="${MINDEE_API_KEY}")\n    # Create request payload\n    request = InvoiceExtractionRequest(\n        file_path=file_path,\n        document_type="invoice"\n    )\n    # Call Mindee Invoice OCR endpoint (via SDK wrapper)\n    response_data = client.process_invoice(request)\n    # Map response to standard response model\n    return response_data\n
